"use client";

import { useEffect, useState } from "react";
import {storedDate,brazilToday} from "@/lib/dates";
import Link from "next/link";
import { Activity, ArrowDownToLine, ArrowUpRight, Bell, Check, ChevronRight, CircleDollarSign, CreditCard, FileText, Headphones, Leaf, MessageSquare, Pencil, Plus, Search, Settings2, ShieldCheck, SlidersHorizontal, Sprout, Users, Wallet, X } from "lucide-react";
import type { LucideIcon } from "lucide-react";
import { Area, AreaChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import { downloadXlsx } from "../../lib/export-xlsx";
import "./business.css";

// These objects come from the authenticated, administrator-only data endpoint.
// eslint-disable-next-line @typescript-eslint/no-explicit-any -- Dynamic administrative form values are validated by the API schema.
type Row = Record<string, any>;
// eslint-disable-next-line @typescript-eslint/no-explicit-any -- Shared shell passes the authenticated API response.
type Props = { view: string; data: any; refresh: () => Promise<void>; notify: (s: string) => void };
const brl = (value: number) => new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format(Number(value) || 0);
const number = (value: number) => new Intl.NumberFormat("pt-BR").format(Number(value) || 0);
const date = (value: string) => value && !Number.isNaN(storedDate(value).getTime()) ? storedDate(value).toLocaleDateString("pt-BR") : "Não informado";
const dateTime = (value: string) => value && !Number.isNaN(storedDate(value).getTime()) ? storedDate(value).toLocaleString("pt-BR", { dateStyle: "short", timeStyle: "short" }) : "Ainda não registrado";
const initials = (name: string) => (name || "P").trim().split(/\s+/).slice(0, 2).map(s => s[0]).join("").toUpperCase();
const labels: Record<string, string> = { active: "Ativo", suspended: "Suspenso", trial: "Em teste", trialing: "Em teste", canceled: "Cancelado", cancelled: "Cancelado", past_due: "Em atraso", unpaid: "Em atraso", pending: "Pendente", paid: "Recebido", succeeded: "Recebido", confirmed: "Recebido", failed: "Falhou", open: "Aberto", in_progress: "Em atendimento", resolved: "Resolvido", closed: "Encerrado", low: "Baixa", normal: "Normal", medium: "Normal", high: "Alta", urgent: "Urgente", lead: "Lead", contacted: "Contatado", interested: "Interessado", demo: "Demonstração", customer: "Cliente pagante", free: "Gratuito", producer: "Produtor", admin: "Administrador" };
const stages = [{ id: "lead", label: "Lead" }, { id: "contacted", label: "Contatado" }, { id: "interested", label: "Interessado" }, { id: "demo", label: "Demonstração" }, { id: "trial", label: "Teste gratuito" }, { id: "customer", label: "Cliente pagante" }, { id: "canceled", label: "Cancelado" }];
const paid = (p: Row) => ["paid", "succeeded", "confirmed"].includes(p.status);

const normalizations: Record<string, string> = { "lead": "lead", "contatado": "contacted", "interessado": "interested", "demonstração": "demo", "teste gratuito": "trial", "cliente pagante": "customer", "cancelado": "canceled", "aberto": "open", "em atendimento": "in_progress", "respondido": "in_progress", "resolvido": "resolved", "fechado": "closed", "baixa": "low", "alta": "high", "urgente": "urgent", "normal": "normal" };
const normalize = (value: string) => normalizations[String(value || "").toLowerCase()] || value;
const status = (value: string) => <span className={`biz-status biz-status-${normalize(value) || "pending"}`}><i />{labels[normalize(value)] || value || "Pendente"}</span>;
function Empty({ icon: Icon = Sprout, title, children }: { icon?: LucideIcon; title: string; children?: React.ReactNode }) { return <div className="biz-empty"><span><Icon size={26} strokeWidth={1.5} /></span><h3>{title}</h3><p>{children}</p></div>; }
function Metric({ icon: Icon, label, value, sub, accent = false }: { icon: LucideIcon; label: string; value: React.ReactNode; sub: string; accent?: boolean }) { return <div className={`biz-metric ${accent ? "biz-metric-accent" : ""}`}><div className="biz-metric-top"><span>{label}</span><Icon size={19} /></div><strong>{value}</strong><small>{sub}</small></div>; }
function Title({ eyebrow = "CAFÉGESTOR BUSINESS", title, description, children }: { eyebrow?: string; title: string; description: string; children?: React.ReactNode }) { return <div className="biz-heading"><div><span className="biz-eyebrow">{eyebrow}</span><h1>{title}</h1><p>{description}</p></div>{children && <div className="biz-heading-actions">{children}</div>}</div>; }
function SearchBox({ value, onChange, placeholder = "Pesquisar por nome ou e-mail..." }: { value: string; onChange: (s: string) => void; placeholder?: string }) { return <div className="biz-search"><Search size={18} /><input value={value} onChange={e => onChange(e.target.value)} placeholder={placeholder} aria-label={placeholder} />{value && <button onClick={() => onChange("")} aria-label="Limpar pesquisa"><X size={15} /></button>}</div>; }
function Modal({ title, subtitle, children, close }: { title: string; subtitle?: string; children: React.ReactNode; close: () => void }) { return <div className="modal-backdrop biz-modal-backdrop" onMouseDown={e => e.target === e.currentTarget && close()}><section className="modal biz-modal" role="dialog" aria-modal="true" aria-label={title}><header><div><h2>{title}</h2>{subtitle && <p>{subtitle}</p>}</div><button className="biz-icon-button" onClick={close} aria-label="Fechar"><X size={21} /></button></header>{children}</section></div>; }
function exportCsv(rows: Row[], name: string) { if (!rows.length) return; const keys = Object.keys(rows[0]); const csv = "\uFEFF" + [keys, ...rows.map(row => keys.map(k => row[k]))].map(row => row.map(cell => `"${String(/^[=+@\-\t\r]/.test(String(cell ?? "")) ? "'" + cell : cell ?? "").replaceAll('"', '""')}"`).join(";")).join("\r\n"); const url = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8;" })); const a = document.createElement("a"); a.href = url; a.download = `${name}-${brazilToday()}.csv`; a.click(); URL.revokeObjectURL(url); }

export default function Business({ view, data, refresh, notify }: Props) {
  const [now] = useState(() => Date.now());
  const [billing, setBilling] = useState<{ configured: boolean; mode: "test" | "live" | null } | null>(null);
  useEffect(() => {
    if (data.profile?.role !== "admin") return;
    const controller = new AbortController();
    void (async () => {
      try {
        const response = await fetch("/api/billing", { cache: "no-store", signal: controller.signal });
        if (!response.ok) return;
        const information = await response.json() as { configured?: unknown; mode?: unknown };
        if (typeof information.configured === "boolean") setBilling({ configured: information.configured, mode: information.mode === "test" || information.mode === "live" ? information.mode : null });
      } catch { /* The authenticated data response still provides the configuration flag. */ }
    })();
    return () => controller.abort();
  }, [data.profile?.role, data.integration?.payments]);
  const [search, setSearch] = useState("");
  const [filter, setFilter] = useState("all");
  const [modal, setModal] = useState("");
  const [selected, setSelected] = useState<Row | null>(null);
  const [draft, setDraft] = useState<Row>({});
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [period, setPeriod] = useState("6");
  const business = data.business || {};
  const users: Row[] = business.users || [];
  const clients = users.filter(u => u.role !== "admin");
  const subscriptions: Row[] = business.subscriptions || [];
  const payments: Row[] = business.payments || [];
  const crm: Row[] = (business.crm || []).map((c: Row) => ({ ...c, stage: normalize(c.stage) }));
  const contacts: Row[] = business.contacts || [];
  const plans: Row[] = data.plans || [];
  const tickets: Row[] = (business.tickets || data.tickets || []).map((t: Row) => ({ ...t, status: normalize(t.status), priority: normalize(t.priority || "normal") }));
  const audit: Row[] = business.audit || [];
  const events: Row[] = business.events || [];
  const settings = data.settings || {};
  const billingConfigured = billing?.configured ?? data.integration?.payments === "configured";
  const billingTest = billing?.mode === "test";
  const billingLabel = billingConfigured ? billingTest ? "Modo de teste" : "Credenciais configuradas" : "Integração pendente";
  const current = view.replace(/^\//, "");
  const getUser = (id: string) => users.find(u => u.id === id);
  const getPlan = (id: string) => plans.find(p => p.id === id);
  const getSubscription = (id: string) => subscriptions.find(s => s.userId === id && ["active", "trial", "trialing", "past_due"].includes(s.status)) || subscriptions.find(s => s.userId === id);
  const active = (s: Row) => s.status === "active" && Boolean(s.verifiedAt) && new Date(s.currentPeriodEnd).getTime() > now;
  const contractPrice = (s: Row) => Number(s.price ?? s.amount ?? s.unitAmount ?? 0);
  const mrr = subscriptions.filter(active).reduce((sum, s) => sum + contractPrice(s) / (s.period === "annual" ? 12 : 1), 0);
  const cash = payments.filter(paid).reduce((sum, p) => sum + Number(p.amount || 0), 0);
  const payingUsers = new Set(subscriptions.filter(s => active(s) && contractPrice(s) > 0).map(s => s.userId));
  const trials = subscriptions.filter(s => ["trial", "trialing"].includes(s.status));
  const canceled = subscriptions.filter(s => ["canceled", "cancelled"].includes(s.status));
  const find = (rows: Row[]) => rows.filter(row => `${row.name || ""} ${row.email || ""} ${row.company || ""} ${row.subject || ""} ${row.id || ""}`.toLowerCase().includes(search.toLowerCase()));
  const months = Array.from({ length: Number(period) }, (_, i) => { const start = new Date(); start.setDate(1); start.setMonth(start.getMonth() - (Number(period) - i - 1)); start.setHours(0, 0, 0, 0); const end = new Date(start); end.setMonth(end.getMonth() + 1); return { month: start.toLocaleDateString("pt-BR", { month: "short" }).replace(".", ""), Clientes: clients.filter(u => storedDate(u.createdAt) < end).length, Recebido: payments.filter(p => paid(p) && storedDate(p.paidAt || p.createdAt) >= start && storedDate(p.paidAt || p.createdAt) < end).reduce((sum, p) => sum + Number(p.amount || 0), 0) }; });
  const close = () => { if (!busy) { setModal(""); setSelected(null); setDraft({}); setError(""); } };
  const open = (type: string, item?: Row, values?: Row) => { setModal(type); setSelected(item || null); setDraft(values || item || {}); setError(""); };
  const mutate = async (entity: string, action: string, values: Row, id?: string) => {
    setBusy(true); setError("");
    try { const response = await fetch("/api/data", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ entity, action, ...(id ? { id } : {}), data: values }) }); const result = await response.json() as { error?: string }; if (!response.ok) throw new Error(result.error || "Não foi possível salvar. Tente novamente."); await refresh(); notify(action === "delete" ? "Registro excluído." : "Alterações salvas com sucesso."); setModal(""); setSelected(null); setDraft({}); return true; } catch (err) { const message = err instanceof Error ? err.message : "Ocorreu um erro ao salvar."; setError(message); notify(message); return false; } finally { setBusy(false); }
  };
  const update = (key: string, value: unknown) => setDraft(d => ({ ...d, [key]: value }));
  const visibleClients = find(clients).filter(u => filter === "all" || (crm.find(c => c.userId === u.id)?.stage || "lead") === filter);
  const visiblePayments = payments.filter(p => { if (period === "all") return true; const cutoff = new Date(); cutoff.setMonth(cutoff.getMonth() - Number(period)); return storedDate(p.paidAt || p.createdAt) >= cutoff; });

  if (data.profile?.role !== "admin") return <div className="biz-restricted panel"><ShieldCheck size={44} strokeWidth={1.4} /><span className="biz-eyebrow">AMBIENTE ADMINISTRATIVO</span><h1>Acesso restrito</h1><p>O CaféGestor Business é exclusivo para administradores autorizados da plataforma.</p><Link className="btn btn-primary" href="/dashboard">Voltar ao CaféGestor</Link></div>;

  const planForm = <form onSubmit={e => { e.preventDefault(); void mutate("plan", selected ? "update" : "create", { name: draft.name, period: draft.period || "monthly", price: Number(draft.price), farmLimit: Number(draft.farmLimit), plotLimit: Number(draft.plotLimit), trialDays: Number(draft.trialDays || 0), order: Number(draft.order || 0), active: draft.active !== false, visible: draft.visible !== false, features: { simulator: !!draft.features?.simulator, reports: !!draft.features?.reports, export: !!draft.features?.export, advanced: !!draft.features?.advanced }, benefits: typeof draft.benefits === "string" ? draft.benefits.split("\n").map((s: string) => s.trim()).filter(Boolean) : draft.benefits || [] }, selected?.id); }}><div className="biz-form-body"><div className="form-grid"><label className="field">Nome do plano<input required maxLength={60} value={draft.name || ""} onChange={e => update("name", e.target.value)} placeholder="Ex.: CaféGestor Pro" /></label><label className="field">Preço (R$)<input required type="number" min="0" step="0.01" value={draft.price ?? ""} onChange={e => update("price", e.target.value)} /></label><label className="field">Periodicidade<select value={draft.period || "monthly"} onChange={e => update("period", e.target.value)}><option value="monthly">Mensal</option><option value="annual">Anual</option></select></label><label className="field">Dias de teste<input type="number" min="0" max="365" value={draft.trialDays ?? 0} onChange={e => update("trialDays", e.target.value)} /></label><label className="field">Limite de fazendas<input required type="number" min="1" value={draft.farmLimit ?? 1} onChange={e => update("farmLimit", e.target.value)} /></label><label className="field">Limite de talhões<input required type="number" min="1" value={draft.plotLimit ?? 5} onChange={e => update("plotLimit", e.target.value)} /></label><label className="field">Ordem de exibição<input type="number" min="0" value={draft.order ?? 0} onChange={e => update("order", e.target.value)} /></label></div><label className="field">Benefícios no site <span className="muted">Um benefício por linha.</span><textarea rows={4} value={Array.isArray(draft.benefits) ? draft.benefits.join("\n") : draft.benefits || ""} onChange={e => update("benefits", e.target.value)} /></label><div className="biz-form-section"><h3>Recursos incluídos</h3><div className="biz-checkbox-grid">{[{ id: "simulator", label: "Simulador de rentabilidade" }, { id: "reports", label: "Relatórios completos" }, { id: "export", label: "Exportação de relatórios" }, { id: "advanced", label: "Gráficos avançados" }].map(f => <label key={f.id} className="biz-check"><input type="checkbox" checked={!!draft.features?.[f.id]} onChange={e => update("features", { ...draft.features, [f.id]: e.target.checked })} />{f.label}</label>)}</div></div><div className="biz-checkbox-grid"><label className="biz-check"><input type="checkbox" checked={draft.active !== false} onChange={e => update("active", e.target.checked)} />Plano ativo</label><label className="biz-check"><input type="checkbox" checked={draft.visible !== false} onChange={e => update("visible", e.target.checked)} />Exibir no site público</label></div><div className="biz-inline-note"><ShieldCheck size={17} /><p>Alterações de preço se aplicam a novas contratações. Contratos existentes mantêm o valor acordado.</p></div>{error && <p className="biz-error" role="alert">{error}</p>}</div><footer><button type="button" className="btn btn-secondary" disabled={busy} onClick={close}>Cancelar</button><button className="btn btn-primary" disabled={busy}>{busy ? "Salvando..." : "Salvar plano"}</button></footer></form>;

  return <div className="biz-page">
    {billingTest && <div className="biz-inline-note"><CreditCard size={18} /><p><strong>Stripe em modo de teste.</strong> Cobranças criadas com esta configuração são de teste e não representam recebimentos reais.</p></div>}
    {current === "business" && <>
      <Title title="Seu negócio, em perspectiva." description="Acompanhe os resultados e os próximos passos do CaféGestor."><span className="biz-live"><i />Dados da plataforma</span><div className="biz-date">{new Date().toLocaleDateString("pt-BR", { day: "numeric", month: "long", year: "numeric" })}</div></Title>
      <div className="biz-welcome"><div><span className="biz-eyebrow">CRESCER É CULTIVAR BOAS RELAÇÕES</span><h2>Cada produtor. Uma nova possibilidade.</h2><p>Uma visão clara da sua operação para tomar decisões com confiança.</p><Link href="/business/clientes">Gerenciar clientes <ArrowUpRight size={17} /></Link></div><div className="biz-welcome-art" aria-hidden="true"><span /><span /><Leaf size={90} strokeWidth={.9} /><Sprout size={112} strokeWidth={.8} /></div></div>
      <div className="biz-metrics"><Metric icon={Users} label="Produtores cadastrados" value={number(clients.length)} sub={`${number(clients.filter(u => u.status === "active").length)} contas ativas`} /><Metric icon={CreditCard} label="Clientes pagantes" value={number(payingUsers.size)} sub={`${number(trials.length)} assinaturas em teste`} /><Metric icon={CircleDollarSign} label="Receita recorrente mensal" value={brl(mrr)} sub="MRR · contratos ativos" accent /><Metric icon={Wallet} label="Receita recebida" value={brl(cash)} sub="Pagamentos confirmados · todo o período" /></div>
      <div className="biz-business-facts"><div><span>Usuários totais</span><strong>{number(users.length)}</strong></div><div><span>Clientes no plano gratuito</span><strong>{number(clients.filter(u => !u.plan || u.plan === "free").length)}</strong></div><div><span>Receita anual estimada · ARR</span><strong>{brl(mrr * 12)}</strong></div><div><span>Cancelamentos / todos os contratos</span><strong>{subscriptions.length ? (canceled.length / subscriptions.length * 100).toLocaleString("pt-BR", { maximumFractionDigits: 1 }) : "0"}%</strong></div></div>
      <div className="biz-dashboard-grid"><section className="panel biz-chart-panel"><div className="biz-panel-heading"><div><h2>Crescimento da comunidade</h2><p>Produtores cadastrados ao longo do tempo</p></div><select className="biz-select" aria-label="Período do gráfico" value={period} onChange={e => setPeriod(e.target.value)}><option value="6">Últimos 6 meses</option><option value="12">Últimos 12 meses</option></select></div><div className="biz-chart"><ResponsiveContainer width="100%" height={245}><AreaChart data={months} margin={{ top: 20, right: 15, left: -24, bottom: 0 }}><defs><linearGradient id="biz-growth" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#557A46" stopOpacity={.2} /><stop offset="100%" stopColor="#557A46" stopOpacity={0} /></linearGradient></defs><CartesianGrid strokeDasharray="4 6" vertical={false} stroke="#e9ede7" /><XAxis dataKey="month" tickLine={false} axisLine={false} tick={{ fill: "#849083", fontSize: 12 }} dy={10} /><YAxis allowDecimals={false} tickLine={false} axisLine={false} tick={{ fill: "#849083", fontSize: 11 }} domain={[0, (max: number) => Math.max(4, max)]} /><Tooltip contentStyle={{ border: "1px solid #e1e7df", borderRadius: 10, fontSize: 13 }} /><Area type="monotone" dataKey="Clientes" stroke="#557A46" strokeWidth={2.5} fill="url(#biz-growth)" activeDot={{ r: 5, fill: "#163D2B" }} /></AreaChart></ResponsiveContainer></div><div className="biz-chart-caption"><span className="biz-legend-dot" />Total acumulado de produtores<span>{clients.length === 0 ? "Seu primeiro cadastro começa esta história." : `${number(clients.length)} produtores fazem parte desta história.`}</span></div></section><section className="panel biz-subscription-summary"><div className="biz-panel-heading"><div><h2>Assinaturas</h2><p>Uma visão da sua base</p></div><CreditCard size={19} /></div><div className="biz-ring"><svg viewBox="0 0 128 128"><circle cx="64" cy="64" r="53" fill="none" stroke="#edf0e9" strokeWidth="10" /><circle cx="64" cy="64" r="53" fill="none" stroke="#557A46" strokeWidth="10" strokeDasharray={`${subscriptions.length ? subscriptions.filter(active).length / subscriptions.length * 333 : 0} 333`} strokeLinecap="round" transform="rotate(-90 64 64)" /></svg><div><strong>{number(subscriptions.length)}</strong><span>assinaturas</span></div></div><div className="biz-distribution"><p><span><i style={{ background: "#557A46" }} />Ativas</span><b>{subscriptions.filter(active).length}</b></p><p><span><i style={{ background: "#c5a965" }} />Em teste</span><b>{trials.length}</b></p><p><span><i style={{ background: "#d5dbd1" }} />Canceladas</span><b>{canceled.length}</b></p></div><Link className="biz-panel-link" href="/business/assinaturas">Ver todas as assinaturas <ChevronRight size={16} /></Link></section></div>
      <div className="biz-dashboard-grid biz-bottom-grid"><section className="panel"><div className="biz-panel-heading"><div><h2>Novos produtores</h2><p>Os últimos a chegar à comunidade</p></div><Link href="/business/clientes">Ver todos <ArrowUpRight size={15} /></Link></div>{clients.length ? <div className="biz-client-list">{[...clients].sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt))).slice(0, 4).map(u => <div key={u.id}><span className="biz-avatar">{initials(u.name)}</span><div><strong>{u.name}</strong><span>{u.email}</span></div><small>{date(u.createdAt)}</small></div>)}</div> : <Empty icon={Users} title="Pronto para receber produtores">Os novos cadastros aparecerão aqui automaticamente.</Empty>}</section><section className="panel"><div className="biz-panel-heading"><div><h2>Seu próximo passo</h2><p>Prepare o terreno para crescer</p></div><Sprout size={20} /></div><div className="biz-setup-list"><Link href="/business/planos"><span><SlidersHorizontal size={19} /></span><div><strong>Organize seus planos</strong><p>Preços, limites e benefícios</p></div><ChevronRight size={16} /></Link><Link href="/business/configuracoes"><span><Settings2 size={19} /></span><div><strong>Cuide da sua marca</strong><p>Textos públicos e canal de suporte</p></div><ChevronRight size={16} /></Link><Link href="/business/assinaturas"><span><CreditCard size={19} /></span><div><strong>{billingConfigured ? "Acompanhe os pagamentos" : "Conecte os pagamentos"}</strong><p>{billingConfigured ? billingTest ? "Stripe configurado · modo de teste" : "Credenciais Stripe configuradas" : "Integração Stripe pendente"}</p></div><ChevronRight size={16} /></Link></div></section></div>
    </>}

    {current === "business/clientes" && <>
      <Title title="Relacionamentos que crescem." description="Conheça seus produtores e acompanhe cada etapa da jornada." />
      <div className="biz-metrics biz-metrics-three"><Metric icon={Users} label="Base de produtores" value={number(clients.length)} sub="Cadastros reais da plataforma" /><Metric icon={MessageSquare} label="Em acompanhamento" value={number(crm.filter(c => ["contacted", "interested", "demo"].includes(c.stage)).length)} sub="Contato, interesse ou demonstração" /><Metric icon={Sprout} label="Clientes pagantes" value={number(payingUsers.size)} sub="Com contrato ativo e pago" /></div>
      <section className="panel"><div className="biz-toolbar"><SearchBox value={search} onChange={setSearch} /><select className="biz-select" value={filter} onChange={e => setFilter(e.target.value)} aria-label="Etapa comercial"><option value="all">Todas as etapas</option>{stages.map(s => <option value={s.id} key={s.id}>{s.label}</option>)}</select><span className="biz-result-count">{visibleClients.length} produtores</span></div>{visibleClients.length ? <div className="table-wrap"><table className="biz-table"><thead><tr><th>Produtor</th><th>Localização</th><th>Plano atual</th><th>Etapa comercial</th><th>Cadastro</th><th /></tr></thead><tbody>{visibleClients.map(u => { const c = crm.find(c => c.userId === u.id); const s = getSubscription(u.id); return <tr key={u.id}><td><div className="biz-person"><span className="biz-avatar">{initials(u.name)}</span><div><strong>{u.name}</strong><span>{u.email}</span></div></div></td><td>{[u.city, u.state].filter(Boolean).join(" / ") || "Não informado"}</td><td>{getPlan(s?.planId || u.planId || u.plan)?.name || "Grátis"}</td><td>{status(c?.stage || "lead")}</td><td>{date(u.createdAt)}</td><td><button className="biz-text-button" onClick={() => open("crm", u, { userId: u.id, stage: c?.stage || "lead", notes: c?.notes || "", task: c?.task || "" })}>Ver perfil <ArrowUpRight size={15} /></button></td></tr>; })}</tbody></table></div> : <Empty icon={Users} title={search || filter !== "all" ? "Nenhum produtor encontrado" : "Seu próximo cliente começa aqui"}>{search || filter !== "all" ? "Tente outra pesquisa ou etapa comercial." : "Os produtores que criarem uma conta entrarão automaticamente no seu CRM."}</Empty>}</section>
    </>}

    {current === "business/usuarios" && <>
      <Title title="Pessoas por trás dos números." description="Gerencie contas, consulte acessos e mantenha a plataforma segura." />
      <section className="panel"><div className="biz-toolbar"><SearchBox value={search} onChange={setSearch} /><select className="biz-select" aria-label="Status da conta" value={filter} onChange={e => setFilter(e.target.value)}><option value="all">Todos os status</option><option value="active">Ativos</option><option value="suspended">Suspensos</option></select><span className="biz-result-count">{users.length} usuários cadastrados</span></div>{find(users).filter(u => filter === "all" || u.status === filter).length ? <div className="table-wrap"><table className="biz-table"><thead><tr><th>Usuário</th><th>Perfil</th><th>Status</th><th>Último acesso</th><th>Cadastro</th><th /></tr></thead><tbody>{find(users).filter(u => filter === "all" || u.status === filter).map(u => <tr key={u.id}><td><div className="biz-person"><span className="biz-avatar">{initials(u.name)}</span><div><strong>{u.name}</strong><span>{u.email}</span></div></div></td><td>{labels[u.role] || u.role}</td><td>{status(u.status || "active")}</td><td>{dateTime(u.lastLogin || u.lastAccess || u.lastLoginAt)}</td><td>{date(u.createdAt)}</td><td><button className="biz-text-button" onClick={() => open("user", u)}>Detalhes <ArrowUpRight size={15} /></button></td></tr>)}</tbody></table></div> : <Empty icon={Users} title="Nenhum usuário encontrado">Ajuste os filtros para encontrar uma conta.</Empty>}</section><div className="biz-inline-note"><ShieldCheck size={18} /><p>Ações administrativas são registradas em auditoria. Dados privados das fazendas permanecem restritos ao produtor.</p></div>
    </>}

    {current === "business/planos" && <>
      <Title title="Um plano para cada jornada." description="Configure a oferta do CaféGestor. As alterações aparecem no site público."><button className="btn btn-primary" onClick={() => open("plan", undefined, { name: "", price: 0, period: "monthly", farmLimit: 1, plotLimit: 5, trialDays: 0, order: plans.length, active: true, visible: true, benefits: [], features: {} })}><Plus size={18} />Criar plano</button></Title>
      <div className="biz-inline-note biz-plan-notice"><ShieldCheck size={18} /><p>Novos preços valem para novas assinaturas. O valor dos contratos existentes é preservado.</p></div>
      <div className="biz-plans">{[...plans].sort((a, b) => (a.order || 0) - (b.order || 0)).map((plan, i) => <section className={`biz-plan-card ${i === 1 ? "biz-plan-featured" : ""}`} key={plan.id}><div className="biz-plan-top"><span className="biz-plan-symbol">{i === 0 ? <Sprout size={25} /> : i === 1 ? <Leaf size={25} /> : <ShieldCheck size={25} />}</span><span className={`biz-plan-state ${plan.active ? "" : "is-off"}`}>{plan.active ? "Ativo" : "Inativo"}</span></div><h2>{plan.name}</h2><p className="biz-plan-period">{plan.price === 0 ? "O primeiro passo na sua gestão" : "Para produzir mais e crescer melhor"}</p><div className="biz-plan-price">{brl(plan.price)}<span>/{plan.period === "annual" ? "ano" : "mês"}</span></div><div className="biz-plan-limits"><span><Check size={15} />{plan.farmLimit} {plan.farmLimit === 1 ? "fazenda" : "fazendas"}</span><span><Check size={15} />Até {plan.plotLimit} talhões</span>{Number(plan.trialDays) > 0 && <span><Check size={15} />{plan.trialDays} dias de teste</span>}</div><div className="biz-plan-benefits">{(plan.benefits || []).map((b: string, index: number) => <p key={index}><Check size={15} />{b}</p>)}</div><div className="biz-plan-visibility"><span className={plan.visible ? "" : "is-off"}><i />{plan.visible ? "Visível no site" : "Oculto no site"}</span><span>Ordem {plan.order || 0}</span></div><div className="biz-plan-actions"><button className="btn btn-secondary" onClick={() => open("plan", plan)}><Pencil size={16} />Editar plano</button><button className="biz-icon-button" title="Excluir plano" aria-label={`Excluir ${plan.name}`} onClick={() => open("deletePlan", plan)}><X size={17} /></button></div></section>)}</div>{plans.length === 0 && <section className="panel"><Empty icon={CreditCard} title="Configure seu primeiro plano">Crie preços, benefícios e limites para os produtores.</Empty></section>}
    </>}

    {current === "business/assinaturas" && <>
      <Title title="Assinaturas, com clareza." description="Acompanhe contratos e o relacionamento financeiro com seus clientes." />
      <div className={`biz-integration${billingConfigured ? " is-configured" : ""}`}><span className="biz-integration-icon"><CreditCard size={25} /></span><div><h3>Stripe · {billingLabel}</h3><p>{billingConfigured ? "As credenciais de cobrança estão configuradas no servidor. Contratos e pagamentos só são confirmados após eventos verificados do provedor. A configuração não confirma a disponibilidade remota do serviço." : "Conecte as credenciais e configure webhooks verificados para habilitar pagamentos recorrentes. Nenhuma cobrança é processada neste momento."}</p></div><span className="biz-tag">{billingConfigured ? billingTest ? "Teste" : "Configurado" : "Não conectado"}</span></div>
      <div className="biz-metrics"><Metric icon={CreditCard} label="Assinaturas ativas" value={subscriptions.filter(active).length} sub="Contratos com status ativo" /><Metric icon={Sprout} label="Em teste gratuito" value={trials.length} sub="Períodos de avaliação" /><Metric icon={CircleDollarSign} label="MRR contratado" value={brl(mrr)} sub="Contratos anuais divididos por 12" /><Metric icon={Users} label="Canceladas" value={canceled.length} sub="Total de contratos cancelados" /></div>
      <section className="panel"><div className="biz-panel-heading"><div><h2>Todos os contratos</h2><p>Valores acordados na contratação</p></div><span className="biz-result-count">{subscriptions.length} registros</span></div>{subscriptions.length ? <div className="table-wrap"><table className="biz-table"><thead><tr><th>Produtor</th><th>Plano</th><th>Valor contratado</th><th>Periodicidade</th><th>Status</th><th>Próxima renovação</th></tr></thead><tbody>{subscriptions.map(s => <tr key={s.id}><td><strong>{getUser(s.userId)?.name || "Usuário indisponível"}</strong><span className="biz-cell-sub">{getUser(s.userId)?.email}</span></td><td>{getPlan(s.planId)?.name || s.planName || "Plano arquivado"}</td><td>{brl(contractPrice(s))}</td><td>{s.period === "annual" ? "Anual" : "Mensal"}</td><td>{status(s.status)}</td><td>{date(s.currentPeriodEnd || s.renewsAt)}</td></tr>)}</tbody></table></div> : <Empty icon={CreditCard} title="Os próximos contratos chegam aqui">Assim que uma assinatura for registrada, você poderá acompanhar o plano, o valor e o status.</Empty>}</section>
    </>}

    {current === "business/financeiro" && <>
      <Title title="Resultados que fazem sentido." description="Separe a receita contratada do que efetivamente entrou no caixa."><button className="btn btn-secondary" disabled={!visiblePayments.length} onClick={() => exportCsv(visiblePayments.map(p => ({ ID: p.id, Cliente: getUser(p.userId)?.name || p.userId, Valor: Number(p.amount || 0), Status: labels[p.status] || p.status, Data: date(p.paidAt || p.createdAt) })), "cafegestor-financeiro")}><ArrowDownToLine size={17} />CSV</button><button className="btn btn-primary" disabled={!visiblePayments.length} onClick={() => { try { downloadXlsx(`cafegestor-financeiro-${brazilToday()}.xlsx`, { title: "Financeiro CaféGestor Business", sheets: [{ name: "Pagamentos", title: "CaféGestor Business · Financeiro", description: `Últimos ${period} meses. Receita recebida corresponde somente a pagamentos confirmados.`, columns: [{ key: "id", label: "Referência", width: 36, format: "text" }, { key: "client", label: "Cliente", width: 30 }, { key: "amount", label: "Valor (R$)", format: "currency" }, { key: "status", label: "Status", width: 18 }, { key: "date", label: "Data", format: "date", width: 16 }], rows: visiblePayments.map(p => { const rawDate = p.paidAt || p.createdAt; const parsed = new Date(rawDate); return { id: String(p.providerId || p.id), client: getUser(p.userId)?.name || p.userId, amount: Number(p.amount || 0), status: labels[p.status] || p.status, date: rawDate && Number.isFinite(parsed.getTime()) ? new Date(Date.UTC(parsed.getFullYear(), parsed.getMonth(), parsed.getDate())) : null }; }) }] }); notify("Relatório Excel exportado."); } catch (err) { notify(err instanceof Error ? err.message : "Não foi possível exportar o relatório."); } }}><ArrowDownToLine size={17} />Exportar Excel</button></Title>
      <div className="biz-metrics"><Metric icon={Wallet} label="Receita recebida" value={brl(visiblePayments.filter(paid).reduce((s, p) => s + Number(p.amount || 0), 0))} sub="Somente pagamentos confirmados" accent /><Metric icon={CircleDollarSign} label="Receita recorrente mensal" value={brl(mrr)} sub="MRR · contratos ativos" /><Metric icon={ArrowUpRight} label="Receita anual estimada" value={brl(mrr * 12)} sub="ARR · MRR multiplicado por 12" /><Metric icon={CreditCard} label="Pagamentos pendentes" value={brl(visiblePayments.filter(p => ["pending", "past_due", "unpaid"].includes(p.status)).reduce((s, p) => s + Number(p.amount || 0), 0))} sub="Ainda não compõem o caixa" /></div>
      <section className="panel biz-chart-panel"><div className="biz-panel-heading"><div><h2>Receita recebida por mês</h2><p>Valores confirmados pelo provedor de pagamento</p></div><select className="biz-select" value={period} onChange={e => setPeriod(e.target.value)} aria-label="Período financeiro"><option value="6">Últimos 6 meses</option><option value="12">Últimos 12 meses</option></select></div><div className="biz-chart"><ResponsiveContainer width="100%" height={240}><AreaChart data={months} margin={{ top: 20, right: 20, left: 0, bottom: 0 }}><defs><linearGradient id="biz-cash" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#557A46" stopOpacity={.22} /><stop offset="100%" stopColor="#557A46" stopOpacity={0} /></linearGradient></defs><CartesianGrid vertical={false} strokeDasharray="4 6" stroke="#e9ede7" /><XAxis dataKey="month" tickLine={false} axisLine={false} tick={{ fill: "#849083", fontSize: 12 }} /><YAxis tickFormatter={v => `R$ ${v}`} tickLine={false} axisLine={false} tick={{ fill: "#849083", fontSize: 11 }} /><Tooltip content={({ active: isActive, payload, label }) => isActive && payload?.length ? <div className="biz-tooltip"><strong>{label}</strong><p>{brl(Number(payload[0]?.value || 0))} recebidos</p></div> : null} /><Area type="monotone" dataKey="Recebido" stroke="#557A46" strokeWidth={2.5} fill="url(#biz-cash)" /></AreaChart></ResponsiveContainer></div></section>
      <section className="panel"><div className="biz-panel-heading"><div><h2>Histórico de pagamentos</h2><p>Recebimentos e pendências no período selecionado</p></div></div>{visiblePayments.length ? <div className="table-wrap"><table className="biz-table"><thead><tr><th>Cliente</th><th>Referência</th><th>Data</th><th>Valor</th><th>Status</th></tr></thead><tbody>{visiblePayments.map(p => <tr key={p.id}><td>{getUser(p.userId)?.name || "Não informado"}</td><td className="biz-mono">{p.providerId || p.id}</td><td>{date(p.paidAt || p.createdAt)}</td><td><strong>{brl(p.amount)}</strong></td><td>{status(p.status)}</td></tr>)}</tbody></table></div> : <Empty icon={Wallet} title="Nenhum pagamento neste período">{billingConfigured ? "Os pagamentos registrados pelo provedor aparecerão aqui após confirmação por eventos verificados." : "Pagamentos confirmados aparecerão aqui após a conexão com o provedor de cobrança."}</Empty>}</section>
    </>}

    {current === "business/suporte" && <>
      <Title title="Perto de quem produz." description="Acolha dúvidas, resolva solicitações e acompanhe cada conversa." />
      <div className="biz-metrics biz-metrics-three"><Metric icon={Headphones} label="Chamados abertos" value={tickets.filter(t => t.status === "open").length} sub="Aguardando atendimento" /><Metric icon={MessageSquare} label="Em atendimento" value={tickets.filter(t => t.status === "in_progress").length} sub="Conversas em andamento" /><Metric icon={Check} label="Resolvidos" value={tickets.filter(t => ["resolved", "closed"].includes(t.status)).length} sub="Solicitações concluídas" /></div>
      <section className="panel"><div className="biz-toolbar"><SearchBox value={search} onChange={setSearch} placeholder="Pesquisar assunto do chamado..." /><select className="biz-select" aria-label="Status do chamado" value={filter} onChange={e => setFilter(e.target.value)}><option value="all">Todos os status</option><option value="open">Abertos</option><option value="in_progress">Em atendimento</option><option value="resolved">Resolvidos</option><option value="closed">Encerrados</option></select></div>{find(tickets).filter(t => filter === "all" || t.status === filter).length ? <div className="table-wrap"><table className="biz-table"><thead><tr><th>Solicitação</th><th>Produtor</th><th>Prioridade</th><th>Status</th><th>Data</th><th /></tr></thead><tbody>{find(tickets).filter(t => filter === "all" || t.status === filter).map(t => <tr key={t.id}><td><strong>{t.subject}</strong><span className="biz-cell-sub">#{String(t.id).slice(0, 8)}</span></td><td>{getUser(t.userId)?.name || "Produtor"}</td><td>{status(t.priority || "normal")}</td><td>{status(t.status)}</td><td>{date(t.createdAt)}</td><td><button className="biz-text-button" onClick={() => open("ticket", t, { ticketId: t.id, message: "", status: t.status, priority: t.priority || "normal" })}>Atender <ArrowUpRight size={15} /></button></td></tr>)}</tbody></table></div> : <Empty icon={Headphones} title={search || filter !== "all" ? "Nenhum chamado encontrado" : "Tudo tranquilo por aqui"}>{search || filter !== "all" ? "Ajuste sua pesquisa ou os filtros." : "As solicitações enviadas pelos produtores aparecerão nesta central."}</Empty>}</section>
    </>}

    {current === "business/configuracoes" && <>
      <Title title="A essência da sua plataforma." description="Personalize a comunicação e os conteúdos públicos do CaféGestor." />
      <div className="biz-settings-layout"><aside className="panel biz-settings-aside"><span className="biz-settings-mark"><Leaf size={29} /></span><h2>Identidade e comunicação</h2><p>Essas informações aparecem no site e na experiência dos produtores.</p><div><ShieldCheck size={18} /><span>Somente configurações públicas são editáveis nesta área.</span></div></aside><section className="panel biz-settings-form"><form onSubmit={e => { e.preventDefault(); void mutate("settings", "update", Object.fromEntries(["platformName", "supportEmail", "description", "notice", "privacy", "terms", "logo", "instagram", "facebook", "website"].map(key => [key, draft[key] ?? settings[key] ?? ""]))); }}><div className="biz-panel-heading"><div><h2>Informações da plataforma</h2><p>Mantenha uma comunicação clara e próxima.</p></div><Settings2 size={20} /></div><div className="biz-form-body"><div className="form-grid"><label className="field">Nome da plataforma<input required maxLength={80} value={draft.platformName ?? settings.platformName ?? "CaféGestor"} onChange={e => update("platformName", e.target.value)} /></label><label className="field">E-mail de suporte<input required type="email" value={draft.supportEmail ?? settings.supportEmail ?? ""} onChange={e => update("supportEmail", e.target.value)} /></label></div><label className="field">Descrição institucional<textarea required rows={3} maxLength={1200} value={draft.description ?? settings.description ?? ""} onChange={e => update("description", e.target.value)} /></label><div className="biz-form-section"><h3><Leaf size={17} />Marca e redes sociais</h3><label className="field">URL do logotipo<input type="url" value={draft.logo ?? settings.logo ?? ""} onChange={e => update("logo", e.target.value)} placeholder="https://..." /></label><div className="form-grid">{[{ key: "instagram", label: "Instagram" }, { key: "facebook", label: "Facebook" }, { key: "website", label: "Site institucional" }].map(social => <label key={social.key} className="field">{social.label}<input type="url" value={draft[social.key] ?? settings[social.key] ?? ""} onChange={e => update(social.key, e.target.value)} placeholder="https://..." /></label>)}</div></div><div className="biz-form-section"><h3><Bell size={17} />Comunicado aos produtores</h3><p className="muted">Deixe em branco para ocultar o aviso.</p><label className="field">Mensagem do comunicado<textarea rows={3} maxLength={1200} value={draft.notice ?? settings.notice ?? ""} onChange={e => update("notice", e.target.value)} placeholder="Uma novidade, manutenção programada ou informação importante..." /></label></div><div className="biz-form-section"><h3><FileText size={17} />Documentos públicos</h3><label className="field">Política de privacidade<textarea rows={6} value={draft.privacy ?? settings.privacy ?? ""} onChange={e => update("privacy", e.target.value)} /></label><label className="field">Termos de uso<textarea rows={6} value={draft.terms ?? settings.terms ?? ""} onChange={e => update("terms", e.target.value)} /></label></div>{error && <p className="biz-error" role="alert">{error}</p>}<div className="biz-settings-save"><p>As mudanças são publicadas ao salvar.</p><button className="btn btn-primary" disabled={busy}>{busy ? "Salvando..." : "Salvar configurações"}<Check size={17} /></button></div></div></form></section></div>
    </>}

    {current === "business/monitoramento" && <>
      <Title title="Visibilidade para cuidar melhor." description="Eventos reais da plataforma e trilha de ações administrativas."><button className="btn btn-secondary" disabled={busy} onClick={async () => { setBusy(true); try { await refresh(); notify("Registros atualizados."); } finally { setBusy(false); } }}><Activity size={17} />{busy ? "Atualizando..." : "Atualizar registros"}</button></Title>
      <div className="biz-metrics biz-metrics-three"><Metric icon={Users} label="Novos cadastros · 30 dias" value={clients.filter(u => now - storedDate(u.createdAt).getTime() < 30 * 86400000).length} sub="Contas de produtores criadas no período" /><Metric icon={Activity} label="Contas ativas" value={users.filter(u => u.status === "active").length} sub="Contas habilitadas na plataforma" /><Metric icon={CreditCard} label="Falhas de pagamento" value={payments.filter(p => p.status === "failed").length} sub="Falhas registradas pelo provedor" /></div>
      <div className="biz-service-grid"><section className="panel biz-service"><span className="biz-service-icon"><ShieldCheck size={23} /></span><div><h3>Banco de dados</h3><p>Esta consulta foi respondida pelo backend autenticado.</p></div><span className="biz-status biz-status-active"><i />Conectado</span></section><section className="panel biz-service"><span className="biz-service-icon"><CreditCard size={23} /></span><div><h3>Stripe{billingTest ? " · Modo de teste" : ""}</h3><p>{billingConfigured ? "Credenciais configuradas. Consulte os eventos registrados para acompanhar ocorrências de cobrança." : "Aguardando credenciais e configuração de webhooks."}</p></div><span className={`biz-status ${billingConfigured && !billingTest ? "biz-status-active" : "biz-status-pending"}`}><i />{billingConfigured ? billingTest ? "Teste" : "Configurado" : "Pendente"}</span></section></div><div className="biz-inline-note"><Activity size={18} /><p>Métricas de disponibilidade e desempenho ainda não estão conectadas a um serviço de observabilidade.</p></div>
      <section className="panel"><div className="biz-panel-heading"><div><h2>Trilha de auditoria</h2><p>Ações administrativas registradas pelo servidor</p></div><span className="biz-result-count">{audit.length} registros</span></div>{audit.length ? <div className="table-wrap"><table className="biz-table"><thead><tr><th>Evento</th><th>Responsável</th><th>Registro</th><th>Data e hora</th></tr></thead><tbody>{[...audit].sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt))).slice(0, 100).map((a, i) => <tr key={a.id || i}><td><strong>{a.action || a.type}</strong><span className="biz-cell-sub">{a.entity || a.description}</span></td><td>{getUser(a.userId || a.actorId)?.name || a.actor || "Sistema"}</td><td className="biz-mono">{a.targetId || a.entityId || "—"}</td><td>{dateTime(a.createdAt)}</td></tr>)}</tbody></table></div> : <Empty icon={Activity} title="A trilha começa com suas ações">Alterações em planos, contas e configurações serão registradas aqui.</Empty>}</section>
      <section className="panel"><div className="biz-panel-heading"><div><h2>Eventos da aplicação</h2><p>Ocorrências e erros registrados pelo backend</p></div></div>{events.length ? <div className="biz-event-list">{[...events].sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt))).slice(0, 50).map((ev, i) => <div key={ev.id || i}><span className={`biz-event-icon ${ev.level === "error" ? "is-error" : ""}`}><Activity size={16} /></span><div><strong>{ev.message || ev.type || ev.event}</strong><p>{ev.description || ev.detail || "Evento registrado"}</p></div><time>{dateTime(ev.createdAt)}</time></div>)}</div> : <Empty icon={Activity} title="Nenhuma ocorrência registrada">Os eventos aparecerão aqui quando forem gerados pelo sistema.</Empty>}</section>
    </>}

    {modal === "plan" && <Modal title={selected ? "Editar plano" : "Criar plano"} subtitle="Defina a oferta e os recursos disponíveis aos produtores." close={close}>{planForm}</Modal>}
    {modal === "deletePlan" && selected && <Modal title="Excluir plano" subtitle="Revise esta ação antes de continuar." close={close}><div className="biz-form-body"><p>Excluir o plano <strong>{selected.name}</strong>? Planos vinculados a contratos não podem ser excluídos. Você pode desativá-los para novas contratações.</p>{error && <p className="biz-error" role="alert">{error}</p>}</div><footer><button className="btn btn-secondary" onClick={close} disabled={busy}>Cancelar</button><button className="btn biz-danger-btn" disabled={busy} onClick={() => void mutate("plan", "delete", {}, selected.id)}>{busy ? "Excluindo..." : "Excluir plano"}</button></footer></Modal>}
    {modal === "crm" && selected && <Modal title={selected.name} subtitle="Perfil comercial do produtor" close={close}><form onSubmit={e => { e.preventDefault(); void mutate("crm", crm.some(c => c.userId === selected.id) ? "update" : "create", draft, crm.find(c => c.userId === selected.id)?.id); }}><div className="biz-form-body"><div className="biz-profile-summary"><span className="biz-avatar biz-avatar-large">{initials(selected.name)}</span><div><strong>{selected.name}</strong><p>{selected.email}</p><p>{selected.phone || "Telefone não informado"}</p></div></div><div className="biz-detail-grid"><div><span>Fazenda / empresa</span><strong>{selected.company || "Não informado"}</strong></div><div><span>Cidade / estado</span><strong>{[selected.city, selected.state].filter(Boolean).join(" / ") || "Não informado"}</strong></div><div><span>Cadastro</span><strong>{date(selected.createdAt)}</strong></div><div><span>Último acesso</span><strong>{dateTime(selected.lastLogin || selected.lastAccess || selected.lastLoginAt)}</strong></div><div><span>Plano atual</span><strong>{getPlan(getSubscription(selected.id)?.planId || selected.planId || selected.plan)?.name || "Grátis"}</strong></div><div><span>Assinatura</span><strong>{labels[getSubscription(selected.id)?.status] || "Sem contrato pago"}</strong></div></div><label className="field">Etapa comercial<select value={draft.stage} onChange={e => update("stage", e.target.value)}>{stages.map(s => <option key={s.id} value={s.id}>{s.label}</option>)}</select></label><label className="field">Observações internas<textarea rows={4} value={draft.notes || ""} onChange={e => update("notes", e.target.value)} placeholder="Contexto e histórico dos contatos com este produtor..." /></label><label className="field">Próxima tarefa de acompanhamento<textarea rows={2} value={draft.task || ""} onChange={e => update("task", e.target.value)} placeholder="Ex.: Conversar sobre a próxima safra." /></label><div className="biz-form-section"><h3>Histórico de acompanhamento</h3>{contacts.filter(c => c.userId === selected.id).length ? contacts.filter(c => c.userId === selected.id).slice(0, 10).map((c, i) => <div className="biz-contact-history" key={c.id || i}><div>{status(c.stage)}<time>{dateTime(c.createdAt)}</time></div>{c.notes && <p>{c.notes}</p>}{c.task && <small>Próximo passo: {c.task}</small>}</div>) : <p className="muted">Os acompanhamentos salvos serão registrados aqui.</p>}</div>{error && <p className="biz-error" role="alert">{error}</p>}</div><footer><button type="button" className="btn btn-secondary" disabled={busy} onClick={close}>Fechar</button><button className="btn btn-primary" disabled={busy}>{busy ? "Salvando..." : "Salvar acompanhamento"}</button></footer></form></Modal>}
    {modal === "user" && selected && <Modal title="Detalhes da conta" subtitle="Informações cadastrais e controle de acesso." close={close}><div className="biz-form-body"><div className="biz-profile-summary"><span className="biz-avatar biz-avatar-large">{initials(selected.name)}</span><div><strong>{selected.name}</strong><p>{selected.email}</p>{status(selected.status || "active")}</div></div><div className="biz-detail-grid"><div><span>Perfil</span><strong>{labels[selected.role] || selected.role}</strong></div><div><span>E-mail verificado</span><strong>{selected.emailVerified === undefined ? "Não disponível" : selected.emailVerified ? "Sim" : "Pendente"}</strong></div><div><span>Cadastro</span><strong>{date(selected.createdAt)}</strong></div><div><span>Último acesso</span><strong>{dateTime(selected.lastLogin || selected.lastAccess || selected.lastLoginAt)}</strong></div></div><div className="biz-form-section"><h3>Histórico de assinaturas</h3>{subscriptions.filter(s => s.userId === selected.id).length ? subscriptions.filter(s => s.userId === selected.id).map(s => <div className="biz-mini-contract" key={s.id}><strong>{getPlan(s.planId)?.name || "Plano arquivado"}</strong>{status(s.status)}<span>{brl(contractPrice(s))}</span></div>) : <p className="muted">Esta conta ainda não possui contratos registrados.</p>}</div>{selected.id === data.profile?.id ? <div className="biz-inline-note"><ShieldCheck size={18} /><p>Você está consultando sua própria conta administrativa.</p></div> : <div className="biz-account-action"><div><h3>{selected.status === "suspended" ? "Reativar conta" : "Suspender conta"}</h3><p>{selected.status === "suspended" ? "Restabeleça o acesso deste usuário à plataforma." : "A suspensão impede o acesso sem excluir os dados da conta."}</p></div><button className={`btn ${selected.status === "suspended" ? "btn-primary" : "biz-danger-btn"}`} disabled={busy} onClick={() => void mutate("user", "update", { status: selected.status === "suspended" ? "active" : "suspended" }, selected.id)}>{busy ? "Salvando..." : selected.status === "suspended" ? "Reativar" : "Suspender"}</button></div>}{error && <p className="biz-error" role="alert">{error}</p>}</div><footer><button className="btn btn-secondary" disabled={busy} onClick={close}>Fechar</button></footer></Modal>}
    {modal === "ticket" && selected && <Modal title={selected.subject} subtitle={`Chamado #${String(selected.id).slice(0, 8)} · ${getUser(selected.userId)?.name || "Produtor"}`} close={close}><form onSubmit={e => { e.preventDefault(); void mutate("ticketReply", "update", { message: draft.message, status: draft.status, priority: draft.priority }, selected.id); }}><div className="biz-form-body"><div className="biz-conversation"><div className="biz-message"><div><strong>{getUser(selected.userId)?.name || "Produtor"}</strong><time>{dateTime(selected.createdAt)}</time></div><p>{selected.message || selected.description}</p></div>{(selected.replies || []).map((r: Row, i: number) => <div className={`biz-message ${r.role === "admin" || getUser(r.userId)?.role === "admin" ? "is-admin" : ""}`} key={r.id || i}><div><strong>{r.role === "admin" || getUser(r.userId)?.role === "admin" ? "Equipe CaféGestor" : r.author || getUser(r.userId)?.name || "Produtor"}</strong><time>{dateTime(r.createdAt || r.date)}</time></div><p>{r.message}</p></div>)}</div><div className="form-grid"><label className="field">Status<select value={draft.status} onChange={e => update("status", e.target.value)}><option value="open">Aberto</option><option value="in_progress">Em atendimento</option><option value="resolved">Resolvido</option><option value="closed">Encerrado</option></select></label><label className="field">Prioridade<select value={draft.priority} onChange={e => update("priority", e.target.value)}><option value="low">Baixa</option><option value="normal">Normal</option><option value="high">Alta</option><option value="urgent">Urgente</option></select></label></div><label className="field">Sua resposta (opcional)<textarea maxLength={5000} rows={4} value={draft.message || ""} onChange={e => update("message", e.target.value)} placeholder="Escreva uma resposta para o produtor..." /></label>{error && <p className="biz-error" role="alert">{error}</p>}</div><footer><button type="button" className="btn btn-secondary" onClick={close} disabled={busy}>Fechar</button><button className="btn btn-primary" disabled={busy}>{busy ? "Salvando..." : draft.message?.trim() ? "Enviar resposta" : "Salvar atendimento"}<ArrowUpRight size={16} /></button></footer></form></Modal>}
  </div>;
}

